export function getCatalogProductById(id: string): CatalogProduct | undefined {
  return CATALOG_PRODUCTS.find((p) => p.id === id);
}

export function getCatalogProductsByGender(gender: "men" | "women" | "kids"): CatalogProduct[] {
  return CATALOG_PRODUCTS.filter((p) => p.gender === gender);
}
